package app.vera.coach.visionbeta;
import android.health.connect.*;
import android.health.connect.datatypes.*;
import android.health.connect.datatypes.units.*;
import android.os.OutcomeReceiver;
import java.time.*;
import java.util.*;
import java.util.function.Consumer;
import org.json.*;
/** Same-origin, fully-contained metrics only: never attribute an entire day to a session. */
final class HealthCardio24 {
 static String sport(int type){switch(type){case ExerciseSessionType.EXERCISE_SESSION_TYPE_BIKING:case ExerciseSessionType.EXERCISE_SESSION_TYPE_BIKING_STATIONARY:return "cycling";case ExerciseSessionType.EXERCISE_SESSION_TYPE_SWIMMING_POOL:case ExerciseSessionType.EXERCISE_SESSION_TYPE_SWIMMING_OPEN_WATER:return "swimming";case ExerciseSessionType.EXERCISE_SESSION_TYPE_RUNNING:case ExerciseSessionType.EXERCISE_SESSION_TYPE_RUNNING_TREADMILL:return "running";case ExerciseSessionType.EXERCISE_SESSION_TYPE_WALKING:return "walking";default:return "";}}
 static final class Metric{String origin,id;long start,end;double value;Metric(String o,String i,long s,long e,double v){origin=o;id=i;start=s;end=e;value=v;}}
 static Double sum(List<Metric> values,String origin,long start,long end){List<Metric> matched=new ArrayList<>();Set<String> ids=new HashSet<>();for(Metric v:values)if(v.origin.equals(origin)&&v.start>=start&&v.end<=end&&v.end>v.start&&Double.isFinite(v.value)&&v.value>=0&&ids.add(v.id))matched.add(v);if(matched.isEmpty())return null;matched.sort(Comparator.comparingLong(v->v.start));long previous=start;double total=0;for(Metric v:matched){if(v.start<previous||v.start-previous>1000)return null;previous=v.end;total+=v.value;}return end-previous<=1000?total:null;}
 static Map<String,NavigableMap<Long,List<Metric>>> index(List<Metric> values){Map<String,NavigableMap<Long,List<Metric>>> out=new HashMap<>();for(Metric m:values)out.computeIfAbsent(m.origin,k->new TreeMap<>()).computeIfAbsent(m.start,k->new ArrayList<>()).add(m);return out;}
 static List<Metric> within(Map<String,NavigableMap<Long,List<Metric>>> index,String origin,long start,long end){List<Metric> out=new ArrayList<>();NavigableMap<Long,List<Metric>> group=index.get(origin);if(group!=null)for(List<Metric> row:group.subMap(start,true,end,false).values())out.addAll(row);return out;}
 static void read(Main a,String ticket,HealthConnectManager manager,TimeInstantRangeFilter range,List<ExerciseSessionRecord> sessions){
  List<Metric> distance=new ArrayList<>(),energy=new ArrayList<>();List<String> warnings=new ArrayList<>();
  Runnable finish=()->enrich(a,ticket,manager,sessions,distance,energy,warnings);
  boolean hasCardio=false;for(ExerciseSessionRecord session:sessions)if(!sport(session.getExerciseType()).isEmpty())hasCardio=true;if(!hasCardio){finish.run();return;}
  Runnable calories=()->{if(!HealthReader.allowed(a,"ACTIVE_CALORIES_BURNED")){warnings.add("Sin permiso para leer energía activa.");finish.run();return;}readPage(a,ticket,manager,ActiveCaloriesBurnedRecord.class,range,new ArrayList<>(),-1,0,rs->{for(ActiveCaloriesBurnedRecord r:rs)energy.add(new Metric(r.getMetadata().getDataOrigin().getPackageName(),r.getMetadata().getId(),r.getStartTime().toEpochMilli(),r.getEndTime().toEpochMilli(),r.getEnergy().getInCalories()/1000));finish.run();},()->{warnings.add("No se pudo leer energía activa.");finish.run();});};
  if(!HealthReader.allowed(a,"DISTANCE")){warnings.add("Sin permiso para leer distancia.");calories.run();return;}
  readPage(a,ticket,manager,DistanceRecord.class,range,new ArrayList<>(),-1,0,rs->{for(DistanceRecord r:rs)distance.add(new Metric(r.getMetadata().getDataOrigin().getPackageName(),r.getMetadata().getId(),r.getStartTime().toEpochMilli(),r.getEndTime().toEpochMilli(),r.getDistance().getInMeters()));calories.run();},()->{warnings.add("No se pudo leer distancia.");calories.run();});
 }
 static boolean ambiguous(long start,long end,long otherStart,long otherEnd){return start<otherEnd&&otherStart<end&&(start!=otherStart||end!=otherEnd);}
 static int[] candidateCounts(List<Metric> values,String origin,long start,long end){int source=0,intersect=0,broad=0;for(Metric v:values){if(!origin.equals(v.origin))continue;source++;if(v.start<end&&v.end>start){intersect++;if(v.start<start-120000||v.end>end+120000||v.end-v.start>end-start+240000)broad++;}}return new int[]{source,intersect,broad};}
 static boolean aggregationEligible(int[] counts,boolean recent){return counts[2]==0&&(counts[1]>0||recent);}
 static void enrich(Main a,String ticket,HealthConnectManager manager,List<ExerciseSessionRecord> sessions,List<Metric> distance,List<Metric> energy,List<String> warnings){
  if(!HealthReadPolicy244.current(a,ticket))return;JSONArray arr=new JSONArray();List<java.util.function.Consumer<Runnable>> jobs=new ArrayList<>();List<ExerciseSessionRecord> sorted=new ArrayList<>(sessions);sorted.sort((x,y)->y.getStartTime().compareTo(x.getStartTime()));Set<String> duplicates=new HashSet<>();
  Map<String,NavigableMap<Long,List<Metric>>> distances=index(distance),energies=index(energy);
  for(ExerciseSessionRecord r:sorted){String origin=r.getMetadata().getDataOrigin().getPackageName(),sport=sport(r.getExerciseType());long start=r.getStartTime().toEpochMilli(),end=r.getEndTime().toEpochMilli();if(end<=start||!duplicates.add(origin+"|"+start+"|"+end+"|"+r.getExerciseType()))continue;
   boolean overlap=false;for(ExerciseSessionRecord other:sorted)if(origin.equals(other.getMetadata().getDataOrigin().getPackageName())&&(ambiguous(start,end,other.getStartTime().toEpochMilli(),other.getEndTime().toEpochMilli())||(start==other.getStartTime().toEpochMilli()&&end==other.getEndTime().toEpochMilli()&&r.getExerciseType()!=other.getExerciseType()))){overlap=true;break;}
   JSONObject o=HealthReader.base(r,r.getStartTime(),r.getStartZoneOffset());JSONArray notices=new JSONArray(warnings);JSONObject diagnostic=new JSONObject();HealthReader.put(o,"sport",sport);if(sport.equals("swimming"))HealthReader.put(o,"swimmingMode",r.getExerciseType()==ExerciseSessionType.EXERCISE_SESSION_TYPE_SWIMMING_POOL?"pool":"open_water");HealthReader.put(o,"exerciseType",r.getExerciseType());HealthReader.put(o,"start",start);HealthReader.put(o,"end",end);HealthReader.put(o,"durationSeconds",(end-start)/1000.0);HealthReader.put(o,"minutes",(end-start)/60000.0);HealthReader.put(o,"title",r.getTitle()==null?"Sesión importada":r.getTitle().toString());
   Double meters=overlap?null:sum(within(distances,origin,start,end),origin,start,end),kcal=overlap?null:sum(within(energies,origin,start,end),origin,start,end);HealthReader.put(o,"distanceMeters",meters);HealthReader.put(o,"energyKcal",kcal);HealthReader.put(o,"metricWarnings",notices);HealthReader.put(o,"metricDiagnostics",diagnostic);int[] dc=candidateCounts(distance,origin,start,end),ec=candidateCounts(energy,origin,start,end);HealthReader.put(diagnostic,"distanceOriginRecords",dc[0]);HealthReader.put(diagnostic,"distanceIntersectingRecords",dc[1]);HealthReader.put(diagnostic,"distanceBroadRecords",dc[2]);HealthReader.put(diagnostic,"overlappingSession",overlap);HealthReader.put(diagnostic,"distanceMethod",meters!=null?"records":"unavailable");arr.put(o);
   if(sport.isEmpty())continue;if(overlap){notices.put("Otra sesión del mismo origen se solapa; no se reparten sus métricas.");continue;}boolean recent=end>=System.currentTimeMillis()-2*86400000L;
   if(meters==null&&HealthReader.allowed(a,"DISTANCE")&&aggregationEligible(dc,recent)&&jobs.size()<12){HealthReader.put(diagnostic,"distanceMethod","aggregate_pending");jobs.add(done->aggregate(a,ticket,manager,origin,start,end,DistanceRecord.DISTANCE_TOTAL,value->{if(value!=null&&Double.isFinite(value.getInMeters())&&value.getInMeters()>=0&&value.getInMeters()<=1000000){HealthReader.put(o,"distanceMeters",value.getInMeters());HealthReader.put(diagnostic,"distanceMethod","health_connect_aggregate");}else{HealthReader.put(diagnostic,"distanceMethod","aggregate_empty");notices.put("Health Connect no aporta distancia para este origen e intervalo.");}},()->{HealthReader.put(diagnostic,"distanceMethod","aggregate_error");notices.put("No se pudo consultar la distancia agregada de esta sesión.");},done));}
   else if(meters==null)notices.put(dc[2]>0?"La distancia disponible abarca más que la sesión; no se asigna el total diario.":"No hay distancia atribuible o se alcanzó el límite de consultas de esta lectura.");
   if(jobs.size()<12)jobs.add(done->aggregate(a,ticket,manager,origin,start,end,ExerciseSessionRecord.EXERCISE_DURATION_TOTAL,value->{if(value!=null&&value>0&&value<=end-start)HealthReader.put(o,"healthDurationSeconds",value/1000.0);},()->notices.put("No se pudo consultar la duración agregada."),done));
   if(kcal==null&&HealthReader.allowed(a,"ACTIVE_CALORIES_BURNED")&&aggregationEligible(ec,recent)&&jobs.size()<12)jobs.add(done->aggregate(a,ticket,manager,origin,start,end,ActiveCaloriesBurnedRecord.ACTIVE_CALORIES_TOTAL,value->{if(value!=null&&Double.isFinite(value.getInCalories())&&value.getInCalories()>=0&&value.getInCalories()<=100000000)HealthReader.put(o,"energyKcal",value.getInCalories()/1000.0);},()->notices.put("No se pudo consultar la energía agregada."),done));
  }runJobs(a,ticket,jobs,0,()->HealthReader.emit(a,ticket,"workouts",arr));
 }
 static void runJobs(Main a,String ticket,List<java.util.function.Consumer<Runnable>> jobs,int index,Runnable done){if(!HealthReadPolicy244.current(a,ticket)||a.isFinishing()||a.isDestroyed())return;if(index>=jobs.size()){done.run();return;}jobs.get(index).accept(()->runJobs(a,ticket,jobs,index+1,done));}
 static <T> void aggregate(Main a,String ticket,HealthConnectManager manager,String origin,long start,long end,AggregationType<T> type,Consumer<T> result,Runnable failure,Runnable done){
  if(!HealthReadPolicy244.current(a,ticket))return;TimeInstantRangeFilter window=new TimeInstantRangeFilter.Builder().setStartTime(Instant.ofEpochMilli(start)).setEndTime(Instant.ofEpochMilli(end)).build();AggregateRecordsRequest<T> request=new AggregateRecordsRequest.Builder<T>(window).addAggregationType(type).addDataOriginsFilter(new DataOrigin.Builder().setPackageName(origin).build()).build();
  try{manager.aggregate(request,a.getMainExecutor(),new OutcomeReceiver<AggregateRecordsResponse<T>,HealthConnectException>(){public void onResult(AggregateRecordsResponse<T> response){if(!HealthReadPolicy244.current(a,ticket))return;result.accept(response.get(type));done.run();}public void onError(HealthConnectException e){if(!HealthReadPolicy244.current(a,ticket))return;failure.run();done.run();}});}catch(Exception e){failure.run();done.run();}
 }
 static <T extends android.health.connect.datatypes.Record> void readPage(Main a,String ticket,HealthConnectManager manager,Class<T> cls,TimeInstantRangeFilter range,List<T> all,long token,int pages,Consumer<List<T>> done,Runnable failure){
  if(a.isFinishing()||a.isDestroyed()||!HealthReadPolicy244.current(a,ticket))return;if(pages>=20){failure.run();return;}ReadRecordsRequestUsingFilters.Builder<T> builder=new ReadRecordsRequestUsingFilters.Builder<T>(cls).setTimeRangeFilter(range).setPageSize(500);if(token!=-1)builder.setPageToken(token);
  try{manager.readRecords(builder.build(),a.getMainExecutor(),new OutcomeReceiver<ReadRecordsResponse<T>,HealthConnectException>(){public void onResult(ReadRecordsResponse<T> result){if(!HealthReadPolicy244.current(a,ticket))return;for(T row:result.getRecords()){String client=row.getMetadata().getClientRecordId();if(!HealthReadPolicy244.ownRecord(row.getMetadata().getDataOrigin().getPackageName(),client))all.add(row);}long next=result.getNextPageToken();if(next==-1)done.accept(all);else if(next==token)failure.run();else readPage(a,ticket,manager,cls,range,all,next,pages+1,done,failure);}public void onError(HealthConnectException e){if(HealthReadPolicy244.current(a,ticket))failure.run();}});}catch(Exception e){failure.run();}
 }
}
